// claims-the-far-shore-is-not-built-at-load.mjs — NO GEOMETRY IS GENERATED FROM THE GROUND ON THE MAIN THREAD WITHOUT A CAMERA.
//
// THE CLASS (Boz's ruling, 2026-10-29; BRIEF-the-far-shore-is-not-built-at-load): geometry GENERATED by sampling the ground
// on the CPU, in a React hook (useFrame / useMemo / useEffect / useLayoutEffect), with no camera input. That is what made
// the revetment's far layer a 3.2 s task on provincetown's cold load: thousands of drawn-ground reads at 5–46 µs each,
// for a mesh the camera never changed. Anything the camera does not change belongs in the bake.
// ⭐ HOW IT DECIDES, FROM THE SOURCE (never a list):
//   · SAMPLERS: every export of src/utils/elevation.js, and the function-valued members makeDrawnGround returns
//     (src/lib/drawnGround.js) — the CPU's readers of the ground's height.
//   · VALUE FLOW, never control: a sampled value taints what it is assigned, added, multiplied, written (`a[i] = v`),
//     pushed or copied into (`new Float32Array(a)`), and a call's result when the callee's own summary passes a parameter
//     through to its return. A value used only as a TEST (an `if`, a ternary's condition, a loop bound) taints nothing it
//     selects: picking which end of a stair is up is not generating geometry from the ground.
//   · A GENERATOR is a function in which a tainted value reaches a GEOMETRY SINK — a BufferAttribute's construction,
//     `setAttribute`, or an attribute's setX/setY/setZ/setXYZ — counting a call of its OWN parameters as a sample
//     (a builder handed a groundAt, like revetmentDrape). Summaries are iterated to a fixpoint across every file.
//   · A hook callback is RED when a generating site in it (its own flow reaching a sink, or a call of a generator) is not
//     CAMERA-GATED: a camera value (`camera`, `cam`, `.camera`, a frustum, or what is computed from them, local helpers
//     included) must reach the site's arguments or a test that selects it — an enclosing `if`, or an `if (…) continue |
//     break | return` before it in its own innermost loop. A whole-frame early return does not select; a timer is not a camera.
//   · A parameter is a sampler only where a call site hands it a sampler-valued argument at that position or key (to a
//     fixed point): revetmentDrape's groundAt is, a water-level record's lowAt is not. A function written at the call site
//     that calls a sampler is sampler-valued (drapeRaws' rawAt), and a call returns a sample when it hands a sampler (or its
//     own sampler parameter) at a SLOT whose reading reaches the callee's return. Judged per slot: a sampler at a slot the
//     callee never reads taints nothing.
// ⚠️ LIMIT, SAID: the flow is followed within ONE hook callback. A value computed in one hook (a useMemo returning an
//   array) and written in another (a useEffect, or a child component's prop) is not connected: InstancedTrees' and
//   StreetLights' anchor arrays were invisible to it for that reason (Groyne, 2026-10-29). Their resolvers no longer sample.
// ⭐ AND THE FAR LAYER'S HIDE IS PER CHUNK (C7): SlabRevetment's near chunks are keyed face AND chunk, and the far meshes
//   hide by the same key, so one near chunk on a long face leaves that face's other far chunks drawn at distance.
// ▶ node checks/claims-the-far-shore-is-not-built-at-load.mjs [--mutants] [-v]
//   Planted pairs (always run): a sample used only as a test → GREEN; the same sample written into a position → RED.
//   --mutants: the far useFrame restored → RED · the same gated by a timer → RED · the far build moved INTO the near
//   useFrame (a hook that reads the camera, but not to select it) → RED · the whole-face hide → RED; the near layer's
//   camera useFrame stays GREEN in the others (the control).
import { readFileSync, readdirSync, statSync } from 'node:fs'
import { join, relative, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { createRequire } from 'node:module'
const require = createRequire(import.meta.url)
const { parse } = require('@babel/parser'), traverse = require('@babel/traverse').default

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const DIRS = ['src/components', 'src/lib', 'src/utils', 'src/preview'].map(d => join(ROOT, d))
const HOOKS = new Set(['useFrame', 'useMemo', 'useEffect', 'useLayoutEffect'])
const ATTR_SETTERS = new Set(['setX', 'setY', 'setZ', 'setXY', 'setXYZ', 'setXYZW'])
const REVETMENT = join(ROOT, 'src/components/SlabRevetment.jsx')
const VERBOSE = process.argv.includes('-v')
const parseSrc = (src, f) => { try { return parse(src, { sourceType: 'module', plugins: ['jsx'], errorRecovery: true }) } catch (e) { throw new Error(`⛔ ${f} does not parse: ${e.message}`) } }

// ── SAMPLERS, read from the source ────────────────────────────────────────────
function samplerNames() {
  const out = new Set()
  // ⭐ elevation.js: an export READS THE GROUND when its body calls into the module's own height holders (`sampler`,
  // `drawn`: the field and the drawn mesh), or calls an export that does. Exports that store, subscribe or pack baked
  // anchors (setDrawnGround, onDrawnGround, groundPairs, …) do not read the ground and are not samplers.
  const ex = new Map()
  traverse(parseSrc(readFileSync(join(ROOT, 'src/utils/elevation.js'), 'utf8'), 'elevation.js'), {
    ExportNamedDeclaration(p) { const d = p.get('declaration'); if (!d.node) return
      const fns = d.isFunctionDeclaration() ? [[d.node.id.name, d]] : d.isVariableDeclaration() ? d.get('declarations').filter(v => v.get('init').isFunction?.()).map(v => [v.node.id.name, v.get('init')]) : []
      for (const [n, f] of fns) { const holders = new Set(), calls = new Set()
        f.traverse({ CallExpression(q) { const c = q.node.callee
          if (c.type === 'MemberExpression' && ['sampler', 'drawn'].includes(baseIdent(c))) holders.add(baseIdent(c))
          const cn = nameOfCallee(c); if (cn) calls.add(cn) } })
        ex.set(n, { reads: holders.size > 0, calls }) } } })
  for (const [n, e] of ex) if (e.reads) out.add(n)
  for (let changed = true; changed;) { changed = false; for (const [n, e] of ex) if (!out.has(n) && [...e.calls].some(c => out.has(c))) { out.add(n); changed = true } }
  // drawnGround.js: the function-valued members makeDrawnGround returns (its partsAt, heightAt)
  traverse(parseSrc(readFileSync(join(ROOT, 'src/lib/drawnGround.js'), 'utf8'), 'drawnGround.js'), {
    FunctionDeclaration(p) { if (p.node.id?.name !== 'makeDrawnGround') return
      p.traverse({ ReturnStatement(r) { if (r.getFunctionParent() !== p) return
        for (const prop of r.node.argument?.properties || []) { const n = prop.key?.name, b = n && p.scope.getBinding(n)
          if (b && (b.path.isFunction() || b.path.get('init')?.isFunction?.())) out.add(n) } } }) } })
  if (!out.size) throw new Error('⛔ no samplers found in src/utils/elevation.js / drawnGround.js — the rule would see nothing')
  return out
}

// ── the analysis: per function, a value-flow summary; per hook, a verdict ────────
const nameOfCallee = (c) => c?.type === 'Identifier' ? c.name : c?.type === 'MemberExpression' && !c.computed ? c.property.name : null
const baseIdent = (n) => { while (n && (n.type === 'MemberExpression' || n.type === 'TSNonNullExpression')) n = n.object; return n?.type === 'Identifier' ? n.name : null }
const paramNames = (fn) => { const out = new Set(); const walk = (p) => { if (!p) return
  if (p.type === 'Identifier') out.add(p.name); else if (p.type === 'AssignmentPattern') walk(p.left)
  else if (p.type === 'ObjectPattern') p.properties.forEach(q => walk(q.value || q.argument)); else if (p.type === 'ArrayPattern') p.elements.forEach(walk)
  else if (p.type === 'RestElement') walk(p.argument) }
  fn.params.forEach(walk); return out }

// a function's parameter slots: [{ pos, key, name }] (key is the property name of an object-pattern parameter, else null)
const paramSlots = (fn) => { const out = []
  fn.params.forEach((p, pos) => { const walk = (q, key) => { if (!q) return
    if (q.type === 'Identifier') out.push({ pos, key, name: q.name }); else if (q.type === 'AssignmentPattern') walk(q.left, key)
    else if (q.type === 'ObjectPattern') q.properties.forEach(r => walk(r.value || r.argument, r.key?.name ?? null)) }
    walk(p, null) })
  return out }
const isLoop = (p) => p.isForStatement() || p.isForOfStatement() || p.isForInStatement() || p.isWhileStatement() || p.isDoWhileStatement()
const exits = (st) => st && (st.type === 'ContinueStatement' || st.type === 'BreakStatement' || st.type === 'ReturnStatement'
  || (st.type === 'BlockStatement' && st.body.length === 1 && exits(st.body[0])))

function analyse(files, SAMPLERS) {
  const fns = new Map()   // name → { path, file, slots }
  const asts = files.map(({ file, src }) => ({ file, ast: parseSrc(src, file) }))
  for (const { file, ast } of asts) traverse(ast, { Function(p) {
    const name = p.node.id?.name || (p.parentPath.isVariableDeclarator() ? p.parentPath.node.id.name : null)
    if (name && !fns.has(name)) fns.set(name, { path: p, file, slots: paramSlots(p.node) }) } })
  const fnName = (p) => { const f = p.getFunctionParent(); if (!f) return null; return f.node.id?.name || (f.parentPath.isVariableDeclarator() ? f.parentPath.node.id.name : null) }
  const summary = new Map()   // name → { generates, passes, returnsSample }
  for (const n of fns.keys()) summary.set(n, { generates: false, passes: false, returnsSample: false })
  // ⭐ Q1 (Zob): a parameter is a SAMPLER only where a call site passes a sampler-valued argument at its position or key
  const samplerParams = new Map([...fns.keys()].map(n => [n, new Set()]))
  const samplerProps = new Set()   // object keys some literal binds to a sampler-valued expression (`groundAt: drawnAt1`)
  // ⭐ a function written at the call site that samples is sampler-valued too: `drapeRaws(built, (x, z) => drawnGroundParts(x, z).raw)`
  const samplesInside = (fn) => { let hit = false
    traverse({ type: 'File', program: { type: 'Program', body: [{ type: 'ExpressionStatement', expression: fn }] } }, { noScope: true,
      CallExpression(q) { const c = nameOfCallee(q.node.callee); if (c && (SAMPLERS.has(c) || samplerProps.has(c))) hit = true } })
    return hit }
  const samplerValued = (e, inFn) => !!e && ((e.type === 'Identifier' && (SAMPLERS.has(e.name) || summary.get(e.name)?.returnsSample || samplerParams.get(inFn)?.has(e.name)))
    || (e.type === 'MemberExpression' && !e.computed && samplerProps.has(e.property.name))
    || ((e.type === 'ArrowFunctionExpression' || e.type === 'FunctionExpression') && samplesInside(e)))

  // the flow inside ONE function body (nested arrows included), given what is known about callees; `gens` are the generating sites
  function flow(fnPath, sParams) {
    const params = new Set(paramSlots(fnPath.node).map(s => s.name)), tainted = new Set(), fromParam = new Set(), gens = []
    let returnsSample = false, passes = false
    const isT = (n) => {
      if (!n) return false
      switch (n.type) {
        case 'Identifier': return tainted.has(n.name)
        case 'MemberExpression': return isT(n.object)
        case 'BinaryExpression': case 'LogicalExpression': return isT(n.left) || isT(n.right)
        case 'UnaryExpression': case 'UpdateExpression': case 'SpreadElement': case 'TSAsExpression': return isT(n.argument ?? n.expression)
        case 'ConditionalExpression': return isT(n.consequent) || isT(n.alternate)          // ⭐ never the test
        case 'ArrayExpression': return n.elements.some(isT)
        case 'ObjectExpression': return n.properties.some(p => isT(p.value ?? p.argument))
        case 'NewExpression': return n.arguments.some(isT)                                    // new Float32Array(tainted)
        case 'CallExpression': {
          const c = nameOfCallee(n.callee)
          if (c && SAMPLERS.has(c)) return true
          if (n.callee.type === 'Identifier' && sParams.has(n.callee.name)) return true      // a sampler handed in, called
          const s = c && summary.get(c)
          if (s?.returnsSample) return true
          if (s?.passes && n.arguments.some(isT)) return true
          // a sampler handed in AT A SLOT whose reading reaches the callee's return (Zob: per slot, judged in this function's own
          // context, so a hook passing its own sampler parameter through is seen and a sampler at an unread slot is not)
          const F = c && fns.get(c)
          if (F && s?.returnsHanded?.length) for (const sl of F.slots) { if (!s.returnsHanded.includes(sl.name)) continue
            const a = n.arguments[sl.pos], v = sl.key == null ? a : a?.type === 'ObjectExpression' ? a.properties.find(q => q.key?.name === sl.key)?.value : null
            if (samplerValued(v, null) || (v?.type === 'Identifier' && sParams.has(v.name))) return true }
          if (n.callee.type === 'MemberExpression' && ['map', 'slice', 'concat', 'filter', 'from'].includes(c) && (isT(n.callee.object) || n.arguments.some(isT))) return true
          return false
        }
        default: return false
      }
    }
    const fromP = (n) => n?.type === 'Identifier' ? (params.has(n.name) || fromParam.has(n.name)) : n?.type === 'MemberExpression' ? fromP(n.object) : false
    for (let pass = 0; pass < 4; pass++) {
      const before = tainted.size + fromParam.size
      gens.length = 0
      fnPath.traverse({
        VariableDeclarator(p) { const init = p.node.init; if (!init) return
          const names = []; const walk = (q) => { if (!q) return; if (q.type === 'Identifier') names.push(q.name); else if (q.type === 'ObjectPattern') q.properties.forEach(r => walk(r.value || r.argument)); else if (q.type === 'ArrayPattern') q.elements.forEach(walk); else if (q.type === 'AssignmentPattern') walk(q.left) }
          walk(p.node.id)
          if (isT(init)) names.forEach(n => tainted.add(n))
          if (fromP(init) || (init.type === 'BinaryExpression' && (fromP(init.left) || fromP(init.right)))) names.forEach(n => fromParam.add(n)) },
        AssignmentExpression(p) { const b = baseIdent(p.node.left) ?? (p.node.left.type === 'Identifier' ? p.node.left.name : null)
          if (b && isT(p.node.right)) tainted.add(b)
          if (b && fromP(p.node.right)) fromParam.add(b) },
        CallExpression(p) { const c = nameOfCallee(p.node.callee), args = p.node.arguments
          if (c === 'push' || c === 'set' || c === 'fill') { const b = baseIdent(p.node.callee.object); if (b && args.some(isT)) tainted.add(b) }
          // sinks
          if (c === 'setAttribute' && isT(args[1])) gens.push({ path: p, why: `setAttribute at line ${p.node.loc?.start.line}` })
          if (ATTR_SETTERS.has(c) && args.slice(1).some(isT)) gens.push({ path: p, why: `${c} at line ${p.node.loc?.start.line}` })
          if (c && summary.get(c)?.generates) gens.push({ path: p, why: `calls ${c} (a generator) at line ${p.node.loc?.start.line}` }) },
        NewExpression(p) { const c = nameOfCallee(p.node.callee); if (/BufferAttribute$/.test(c || '') && p.node.arguments.some(isT)) gens.push({ path: p, why: `new ${c} at line ${p.node.loc?.start.line}` }) },
        ReturnStatement(p) { if (p.getFunctionParent() !== fnPath) return
          if (isT(p.node.argument)) returnsSample = true
          if (fromP(p.node.argument)) passes = true },
      })
      if (tainted.size + fromParam.size === before) break
    }
    return { generates: gens.length > 0, gens, returnsSample, passes }
  }

  for (let it = 0; it < 16; it++) {
    let changed = false
    // the call sites: which parameters are handed a sampler, and which object keys carry one
    for (const { ast } of asts) traverse(ast, {
      ObjectProperty(p) { const k = p.node.key?.name; if (k && !samplerProps.has(k) && samplerValued(p.node.value, fnName(p))) { samplerProps.add(k); changed = true } },
      CallExpression(p) { const c = nameOfCallee(p.node.callee), F = c && fns.get(c); if (!F) return
        const inFn = fnName(p)
        p.node.arguments.forEach((a, pos) => { for (const sl of F.slots.filter(sl => sl.pos === pos)) {
          const v = sl.key == null ? a : a.type === 'ObjectExpression' ? a.properties.find(q => q.key?.name === sl.key)?.value : null
          if (samplerValued(v, inFn) && !samplerParams.get(c).has(sl.name)) { samplerParams.get(c).add(sl.name); changed = true } } }) } })
    for (const [n, f] of fns) {
      const r = flow(f.path, samplerParams.get(n)), s = summary.get(n)
      // returnsSample must not leak a handed-in sampler's taint to every caller: judged with no sampler parameters
      const rs = flow(f.path, new Set()).returnsSample
      // …and returnsHanded: the SLOTS whose sampler, if one is handed there, reaches the return (drapeRaws' rawAt), each judged alone
      const rh = f.slots.filter(sl => flow(f.path, new Set([sl.name])).returnsSample).map(sl => sl.name)
      if (r.generates !== s.generates || r.passes !== s.passes || rs !== s.returnsSample || rh.join() !== (s.returnsHanded || []).join()) { changed = true; summary.set(n, { generates: r.generates, passes: r.passes, returnsSample: rs, returnsHanded: rh }) }
    }
    if (!changed) break
  }

  // ⭐ ITEM 5 (Zob): a generating site is CAMERA-GATED only when a camera value reaches its arguments, or a test that
  // SELECTS it — an enclosing `if`, or an `if (…) continue|break|return` before it in its own innermost loop. A camera
  // read anywhere else in the hook (an early return for the whole frame) does not select what is built.
  const hooks = []
  for (const { file, ast } of asts) traverse(ast, { CallExpression(p) {
    const hook = p.node.callee.type === 'Identifier' ? p.node.callee.name : null
    if (!HOOKS.has(hook)) return
    const cb = p.get('arguments.0'); if (!cb?.isFunction?.()) return
    const r = flow(cb, new Set())
    if (!r.generates) return
    const camT = new Set(['camera', 'cam', 'frustum'])
    const hasCam = (node) => { let hit = false; traverse(node, { noScope: true, Identifier(q) { if (camT.has(q.node.name)) hit = true },
      MemberExpression(q) { if (!q.node.computed && q.node.property.name === 'camera') hit = true } }); return hit }
    const wrap = (n) => ({ type: 'File', program: { type: 'Program', body: [{ type: 'ExpressionStatement', expression: n }] } })
    for (let pass = 0; pass < 6; pass++) { const before = camT.size
      cb.traverse({ VariableDeclarator(q) { const id = q.node.id; if (id.type !== 'Identifier' || !q.node.init) return
        if (hasCam(wrap(q.node.init))) camT.add(id.name) } })
      if (camT.size === before) break }
    const gated = (g) => {
      if (g.path.node.arguments?.some(a => hasCam(wrap(a)))) return true
      let q = g.path, loop = null
      while (q && q !== cb) { if (isLoop(q)) { loop = q; break } q = q.parentPath }
      q = g.path
      while (q && q !== (loop ?? cb)) {
        const par = q.parentPath
        if (par?.isIfStatement() && q.key !== 'test' && hasCam(wrap(par.node.test))) return true
        if (loop && par && (par.isBlockStatement() || par.isProgram()) && Array.isArray(par.node.body)) {
          for (const st of par.node.body.slice(0, q.key)) if (st.type === 'IfStatement' && exits(st.consequent) && hasCam(wrap(st.test))) return true
        }
        q = par
      }
      return false
    }
    const open = r.gens.filter(g => !gated(g))
    hooks.push({ file: relative(ROOT, file), line: p.node.loc?.start.line, hook, camera: open.length === 0, why: (open[0] ?? r.gens[0]).why })
  } })
  return { hooks, summary, samplerParams }
}

const repoFiles = () => { const out = []; const walk = (d) => { for (const n of readdirSync(d)) { const p = join(d, n)
  if (statSync(p).isDirectory()) walk(p); else if (/\.(m?js|jsx)$/.test(n)) out.push({ file: p, src: readFileSync(p, 'utf8') }) } }
  DIRS.forEach(walk); return out }
const SAMPLERS = samplerNames()
const red = (r) => r.hooks.filter(h => !h.camera)

// ── the per-chunk hide (C7), read off SlabRevetment.jsx ───────────────────────
function hideIsPerChunk(src) {
  const ast = parseSrc(src, 'SlabRevetment.jsx'); let added = null, keyed = null
  traverse(ast, {
    CallExpression(p) { const c = p.node.callee
      if (c.type === 'MemberExpression' && c.property.name === 'add' && baseIdent(c.object) === 'nearKeys') added = p.node.arguments[0] },
    ObjectProperty(p) { if (p.node.key?.name !== 'key' || !p.parentPath.parentPath.isCallExpression() || nameOfCallee(p.parentPath.parentPath.node.callee) !== 'push') return
      // the value, or (a shorthand / an identifier) the template its binding is initialised with
      const v = p.node.value
      keyed ??= v.type === 'Identifier' ? (p.scope.getBinding(v.name)?.path.node.init ?? v) : v } })
  const parts = (n) => n?.type === 'TemplateLiteral' ? n.expressions.length : 0
  return { ok: parts(added) >= 2 && parts(keyed) >= 2, added: added && src.slice(added.start, added.end), keyed: keyed && src.slice(keyed.start, keyed.end) }
}

const bad = []
const say = (ok, what) => { console.log(`  ${ok ? '✅' : '⛔'} ${what}`); if (!ok) bad.push(what) }
const files = repoFiles()
console.log(`── no geometry is generated from the ground in a hook without a camera (samplers: ${[...SAMPLERS].join(', ')})`)
const R = analyse(files, SAMPLERS)
const near = R.hooks.find(h => h.file.endsWith('SlabRevetment.jsx') && h.hook === 'useFrame')
say(!!near && near.camera, `the near layer's useFrame generates and reads the camera (the control)${near ? ` — ${near.file}:${near.line}` : ' — NOT FOUND: the rule cannot see the near build'}`)
// ⚠️ KNOWN OPEN (Boz ruled, 2026-10-29): hits this rule sees and the kit has not closed, each with WHY and WHAT CLOSES IT. One
// entry absorbs ONE hit of its hook kind in its file: a further hit there, or anywhere else, is RED; an entry nothing hits
// any more is RED too (close it here, in the same commit as the fix).
const OPEN = []
const allReds = red(R), left = OPEN.map(o => ({ ...o, hit: false }))
const reds = allReds.filter(h => { const o = left.find(o => !o.hit && o.file === h.file && o.hook === h.hook); if (o) { o.hit = true; return false } return true })
say(reds.length === 0, `${R.hooks.length} hook(s) generate from the ground; ${reds.length} without a camera, beyond the ${OPEN.length} known open${reds.map(h => `\n       ⛔ ${h.file}:${h.line} ${h.hook}`).join('')}`)
for (const o of left) say(o.hit, `${o.hit ? '⚠️ OPEN' : 'a known-open entry nothing hits any more (close it)'}: ${o.file} ${o.hook} — ${o.why}. Closes: ${o.closes}`)
if (VERBOSE) for (const h of R.hooks) console.log(`     ${h.camera ? 'camera' : 'NONE  '} ${h.file}:${h.line} ${h.hook} — ${h.why}`)
const hide = hideIsPerChunk(readFileSync(REVETMENT, 'utf8'))
say(hide.ok, `the far layer hides per chunk: near keys ${hide.added} · far keys ${hide.keyed}`)

// planted pairs: value vs control (Boz, 2026-10-29) — the refinement cannot drift to "any read" or "no read" unseen
console.log('── planted pairs')
const planted = (body, pre = '') => ({ file: join(ROOT, 'src/components/__planted__.jsx'), src: `import * as THREE from 'three'\nimport { getElevationRaw } from '../utils/elevation'\n${pre}function Planted({ a, b, built }) {\n  const g = useMemo(() => {\n${body}\n  }, [])\n}\n` })
const asTest = planted(`    const down = getElevationRaw(b[0], b[1]) <= getElevationRaw(a[0], a[1])\n    const p = down ? [a[0], 0, a[1], b[0], 0, b[1]] : [b[0], 0, b[1], a[0], 0, a[1]]\n    const geo = new THREE.BufferGeometry(); geo.setAttribute('position', new THREE.Float32BufferAttribute(p, 3)); return geo`)
const asValue = planted(`    const ya = getElevationRaw(a[0], a[1])\n    const p = [a[0], ya, a[1], b[0], 0, b[1]]\n    const geo = new THREE.BufferGeometry(); geo.setAttribute('position', new THREE.Float32BufferAttribute(p, 3)); return geo`)
const p1 = red(analyse([...files, asTest], SAMPLERS)).length - allReds.length, p2 = red(analyse([...files, asValue], SAMPLERS)).length - allReds.length
say(p1 === 0, `a sampled height used only as a TEST (which end is up) → GREEN`)
say(p2 === 1, `the same height written into a position → RED`)
// per slot (Zob): a helper passing ITS OWN sampler parameter through to drapeRaws is seen; a sampler at a slot never read is not
const passThrough = planted(`    return lift(built, getElevationRaw)`, `function lift(built, groundAt) { const r = drapeRaws(built, groundAt); built.geometry.setAttribute('aDrawnRaw', new THREE.BufferAttribute(r, 1)) }\n`)
const unread = planted(`    const r = keepFirst(a, getElevationRaw)\n    const geo = new THREE.BufferGeometry(); geo.setAttribute('position', new THREE.Float32BufferAttribute(r, 3)); return geo`, `function keepFirst(a, unused) { return a }\n`)
const p3 = red(analyse([...files, passThrough], SAMPLERS)).length - allReds.length, p4 = red(analyse([...files, unread], SAMPLERS)).length - allReds.length
say(p3 === 1, `a helper handing its own sampler parameter to drapeRaws, its result written → RED`)
say(p4 === 0, `a sampler handed at a slot the callee never reads → GREEN`)

if (process.argv.includes('--mutants')) {
  console.log('── mutants (each must turn it RED; the near useFrame stays GREEN)')
  const src = readFileSync(REVETMENT, 'utf8'), anchor = '  // ── THE NEAR LAYER — the detailed drape and the stones, by the camera ────────'
  if (!src.includes(anchor)) throw new Error('⛔ mutant anchor gone from SlabRevetment.jsx')
  const FAR = `  useFrame(() => {\n    for (const f of faces) { const [G] = drapeLattices({ poly: f.poly, crestAt: f.crestAt, crestBreaks: f.crestBreaks, octaves: [1] })\n      groundRelative(revetmentDrape({ poly: f.poly, crestAt: f.crestAt, toeAt: f.toeAt, berm: f.berm, groundAt: f.groundAt, waterY: f.waterY, globals: G })) }\n  })\n`
  const TIMER = `  useEffect(() => { const id = setTimeout(() => { for (const f of faces) groundRelative(revetmentDrape({ poly: f.poly, crestAt: f.crestAt, groundAt: f.groundAt, octaves: 1 })) }, 1000); return () => clearTimeout(id) }, [faces])\n`
  const swap = (s2) => files.map(f => f.file === REVETMENT ? { ...f, src: s2 } : f)
  let alive = 0
  // ⭐ Zob: the far build moved INTO the near useFrame — a hook that reads the camera, where the build used to live. The camera
  // must select what is built there, so this is RED too.
  const nearAnchor = '    const drape = [], stones = [], nearKeys = new Set()\n'
  if (!src.includes(nearAnchor)) throw new Error('⛔ near-useFrame mutant anchor gone from SlabRevetment.jsx')
  const INTO = nearAnchor + `    for (const f of faces) groundRelative(revetmentDrape({ poly: f.poly, crestAt: f.crestAt, toeAt: f.toeAt, berm: f.berm, groundAt: f.groundAt, waterY: f.waterY, globals: f.G1 }))\n`
  for (const [name, s2] of [['the far useFrame restored', src.replace(anchor, FAR + anchor)], ['the far build gated by a timer', src.replace(anchor, TIMER + anchor)],
    ['the far build moved into the near useFrame', src.replace(nearAnchor, INTO)]]) {
    const r = analyse(swap(s2), SAMPLERS), n = r.hooks.find(h => h.file.endsWith('SlabRevetment.jsx') && h.hook === 'useFrame' && h.camera)
    const into = name.includes('into the near'), caught = red(r).length > allReds.length
    console.log(`  mutant: ${name} → ${caught ? 'RED ✓' : 'GREEN ✗'}${n || into ? '' : ' (and the near control vanished)'}`); if (!caught || (!n && !into)) alive++ }
  { const a = 'nearKeys.add(`${f.key}#${k}`)'; if (!src.includes(a)) throw new Error('⛔ hide mutant target gone')
    const caught = !hideIsPerChunk(src.replace(a, 'nearKeys.add(f.key)')).ok
    console.log(`  mutant: the whole-face hide → ${caught ? 'RED ✓' : 'GREEN ✗'}`); if (!caught) alive++ }
  if (alive) bad.push(`${alive} mutant(s) survived`)
}
console.log(bad.length ? `⛔ ${bad.length} failed` : '✅ nothing generates geometry from the ground at load without a camera, and the far layer hides per chunk')
process.exit(bad.length ? 1 : 0)
